SELECT T1.SUBJECT_KEY, T1.SUBJECT_TITLE, T1.OFFER_DEPT_NAME, COUNT(T1.SUBJECT_KEY) AS num_subject_offerings, SUM(T2.TOTAL_UNITS) AS total_units, SUM(T1.NUM_ENROLLED_STUDENTS) AS total_enrolled_students FROM SUBJECT_OFFERED T1 JOIN SUBJECT_OFFERED_SUMMARY T2 ON T1.COMPOSITE_SUBJECT_KEY = T2.COMPOSITE_SUBJECT_KEY WHERE T1.TERM_CODE = '2012SU' AND T1.OFFER_DEPT_NAME = 'Harvard Cross-Enrollment Prog' GROUP BY T1.SUBJECT_KEY, T1.SUBJECT_TITLE, T1.OFFER_DEPT_NAME